import type { WorkspaceApi } from "../../src/types.js";

const emptyDiagnostics = {
  diagnostics: [],
  counts: { error: 0, warning: 0, information: 0, hint: 0 },
  total: 0,
  inspected: 0,
  matching: 0,
  incomplete: false,
  snapshotId: "a".repeat(64),
  truncated: false,
};
export const workspace: WorkspaceApi = {
  show: async ({ uri }) => ({ uri, version: 1, dirty: false }),
  workspaceSymbols: async () => ({
    symbols: [],
    truncated: false,
    omitted: 0,
    scanned: 0,
    scanLimitReached: false,
    consistency: "live",
  }),
  definition: async () => ({
    uri: "vfs:/project/file",
    version: 1,
    dirty: false,
    locations: [],
    truncated: false,
    omitted: 0,
  }),
  references: async () => ({
    uri: "vfs:/project/file",
    version: 1,
    dirty: false,
    locations: [],
    truncated: false,
    omitted: 0,
  }),
  hover: async () => ({
    uri: "vfs:/project/file",
    version: 1,
    dirty: false,
    untrusted: true,
    hovers: [],
    truncated: false,
    omitted: 0,
  }),
  documentSymbols: async () => ({
    symbols: [],
    truncated: false,
    omitted: 0,
    scanned: 0,
    scanLimitReached: false,
    consistency: "document-version",
    version: 1,
  }),
  diff: async () => ({ shown: true }),
  format: async ({ uri, version }) => ({
    uri,
    version,
    dirty: false,
    edits: [],
    editCount: 0,
    applied: false,
  }),
  rename: async ({ uri, version }) => ({
    uri,
    version,
    dirty: false,
    providerResult: false,
    preview: {
      previewAvailable: false,
      applicationSupported: false,
      supported: false,
      applicable: false,
      complete: false,
      reasons: ["NO_EDIT"],
      documents: [],
    },
  }),
  codeActions: async ({ uri, version }) => ({
    uri,
    version,
    dirty: false,
    actions: [],
    truncated: false,
  }),
  roots: async () => [{ uri: "memfs:/project", name: "project", index: 0 }],
  context: async () => ({ roots: [], tabs: [], truncated: false }),
  list: async ({ uri }) => ({
    uri,
    entries: [],
    truncated: false,
    blockedEntries: 0,
    omittedEntries: 0,
    incomplete: false,
  }),
  read: async ({ uri }) => ({
    uri,
    text: "unsaved buffer",
    version: 4,
    dirty: true,
    languageId: "abap",
    lineCount: 1,
    startLine: 0,
    endLine: 1,
    requestedRange: {
      start: { line: 0, character: 0 },
      end: { line: 0, character: 14 },
    },
    returnedRange: {
      start: { line: 0, character: 0 },
      end: { line: 0, character: 14 },
    },
    truncated: false,
  }),
  readSymbol: async (input) => ({
    ...(await workspace.read(input)),
    symbol: {
      name: input.name,
      kind: 5,
      range: {
        start: { line: 0, character: 0 },
        end: { line: 0, character: 14 },
      },
      selectionRange: {
        start: { line: 0, character: 0 },
        end: { line: 0, character: 6 },
      },
    },
  }),
  search: async ({ uri, query }) => ({
    uri,
    query,
    matches: [],
    filesSearched: 0,
    consistency: "live",
    limits: [],
    truncated: false,
    incomplete: false,
    errors: [],
  }),
  edit: async ({ uri, version }) => ({
    uri,
    version: version + 1,
    dirty: true,
  }),
  save: async ({ uri, version }) => ({ uri, version, dirty: false }),
  waitForDiagnostics: async ({ uri, version }) => ({
    uri,
    ...emptyDiagnostics,
    outcome: "timeout",
    documentVersion: version,
    capturedAt: new Date().toISOString(),
    analysisComplete: "unknown",
  }),
  diagnostics: async ({ uri }) => ({ uri, ...emptyDiagnostics }),
};
